(()=>{
 'use strict';window.YamaDownloads={async render(){const host=document.querySelector('#portal-download-list');try{const response=await fetch('portal-downloads.json',{cache:'no-store'});if(!response.ok)throw new Error();const report=await response.json();const checked=Date.parse(report.checkedAt);if(!Number.isFinite(checked)||Date.now()-checked>86400000||Date.now()<checked)throw new Error();const allowed=new Set(['/portal-download/windows-installer','/portal-download/windows-portable','https://updates.yamachat.eu/yamaportal/Yamaportal-Setup-latest.exe','https://updates.yamachat.eu/yamaportal/Yamaportal-Portable-latest.exe']);host.replaceChildren();for(const item of report.downloads||[]){if(!allowed.has(item.url)||item.available!==true)continue;const a=document.createElement('a');a.className='secondary';a.href=item.url;a.textContent=item.label;host.append(a);}if(!host.children.length)throw new Error();const note=document.createElement('p');note.className='caption';note.textContent=report.preview?'Místní testovací balíčky Windows x64. Nejsou podepsané; veřejné vydání se připravuje.':'Windows x64';host.append(note);}catch{if(host)host.textContent='Windows balíčky připravujeme k vydání. Zatím můžeš používat web nebo nainstalovat PWA.';}}};
})();
